describe('Search Results Category Filter', () => {
  beforeEach(() => {
    cy.visit('/search');
    cy.get('[data-testid="search-input"]').type('test product');
    cy.get('[data-testid="search-button"]').click();
    cy.get('[data-testid="search-results"]').should('be.visible');
  });

  it('should filter search results by single category checkbox', () => {
    cy.get('[data-testid="category-filter-section"]').should('be.visible');
    cy.get('[data-testid="category-checkbox-electronics"]').should('not.be.checked');

    cy.get('[data-testid="category-checkbox-electronics"]').check();
    cy.get('[data-testid="category-checkbox-electronics"]').should('be.checked');

    cy.get('[data-testid="search-results-container"]').should('exist');
    cy.get('[data-testid="result-item"]').each(($item) => {
      cy.wrap($item).should('contain', 'Electronics');
    });

    cy.get('[data-testid="results-count"]').should('contain', /\d+/);
  });

  it('should filter search results by multiple category checkboxes', () => {
    cy.get('[data-testid="category-checkbox-electronics"]').check();
    cy.get('[data-testid="category-checkbox-books"]').check();

    cy.get('[data-testid="category-checkbox-electronics"]').should('be.checked');
    cy.get('[data-testid="category-checkbox-books"]').should('be.checked');

    cy.get('[data-testid="search-results-container"]').should('exist');
    cy.get('[data-testid="result-item"]').should('have.length.greaterThan', 0);

    cy.get('[data-testid="result-item"]').each(($item) => {
      cy.wrap($item).invoke('text').then((text) => {
        expect(text).to.match(/Electronics|Books/);
      });
    });
  });

  it('should uncheck category filter and show all results', () => {
    cy.get('[data-testid="category-checkbox-electronics"]').check();
    cy.get('[data-testid="category-checkbox-electronics"]').should('be.checked');

    const initialCount = cy.get('[data-testid="result-item"]').its('length');

    cy.get('[data-testid="category-checkbox-electronics"]').uncheck();
    cy.get('[data-testid="category-checkbox-electronics"]').should('not.be.checked');

    cy.get('[data-testid="search-results-container"]').should('exist');
    cy.get('[data-testid="result-item"]').its('length').should('be.greaterThan', 0);
  });

  it('should handle no results when filtering by category', () => {
    cy.get('[data-testid="category-checkbox-nonexistent"]').check();

    cy.get('[data-testid="search-results-container"]').should('exist');
    cy.get('[data-testid="no-results-message"]').should('be.visible');
    cy.get('[data-testid="no-results-message"]').should('contain', 'No results found');
    cy.get('[data-testid="result-item"]').should('have.length', 0);
  });

  it('should persist category filter when navigating back', () => {
    cy.get('[data-testid="category-checkbox-electronics"]').check();
    cy.get('[data-testid="category-checkbox-electronics"]').should('be.checked');

    cy.get('[data-testid="result-item"]').first().click();
    cy.get('[data-testid="product-detail"]').should('be.visible');

    cy.go('back');
    cy.get('[data-testid="search-results"]').should('be.visible');
    cy.get('[data-testid="category-checkbox-electronics"]').should('be.checked');
  });

  it('should update results count when toggling category filters', () => {
    cy.get('[data-testid="results-count"]').invoke('text').then((initialText) => {
      const initialCount = parseInt(initialText.match(/\d+/)[0]);

      cy.get('[data-testid="category-checkbox-electronics"]').check();
      cy.get('[data-testid="results-count"]').invoke('text').then((filteredText) => {
        const filteredCount = parseInt(filteredText.match(/\d+/)[0]);
        expect(filteredCount).to.be.lessThanOrEqual(initialCount);
      });
    });
  });

  it('should handle rapid checkbox toggling without errors', () => {
    cy.get('[data-testid="category-checkbox-electronics"]').check();
    cy.get('[data-testid="category-checkbox-electronics"]').uncheck();
    cy.get('[data-testid="category-checkbox-electronics"]').check();
    cy.get('[data-testid="category-checkbox-electronics"]').uncheck();

    cy.get('[data-testid="search-results-container"]').should('exist');
    cy.get('[data-testid="category-checkbox-electronics"]').should('not.be.checked');
  });

  it('should display category filter section with all available categories', () => {
    cy.get('[data-testid="category-filter-section"]').should('be.visible');
    cy.get('[data-testid="category-filter-label"]').should('contain', 'Categories');

    const expectedCategories = ['Electronics', 'Books', 'Clothing', 'Home'];
    expectedCategories.forEach((category) => {
      cy.get(`[data-testid="category-checkbox-${category.toLowerCase()}"]`).should('exist');
      cy.get(`[data-testid="category-label-${category.toLowerCase()}"]`).should('contain', category);
    });
  });
});
